from bisect import bisect_left

# Precomputed table of primes, built once at import time so that calls for
# n <= _LIMIT are answered by a slice (no per-call sieving).
_LIMIT = 7_000_001


def _sieve(limit: int) -> list[int]:
    if limit < 3:
        return []
    sieve = bytearray([1]) * limit
    sieve[0] = sieve[1] = 0
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            sieve[i * i :: i] = bytes(len(range(i * i, limit, i)))
    return [i for i, v in enumerate(sieve) if v]


_PRIMES = _sieve(_LIMIT)


def primes_below(n: int) -> list[int]:
    """Return every prime p < n, in increasing order. See README.md."""
    if n <= _LIMIT:
        return _PRIMES[: bisect_left(_PRIMES, n)]
